"""Complete SQL-text adapter for the offline synthetic order dataset."""


def _sql_literal(value):
    """Encode a string as a SQLite string literal: double any embedded quotes and wrap in single quotes."""
    if not isinstance(value, str):
        raise TypeError(f"expected str, got {type(value).__name__}")
    return "'" + value.replace("'", "''") + "'"


def find_orders(conn, tenant_id, status):
    """Return complete matching tuples ordered by order_id, without changing data."""
    if not isinstance(tenant_id, str) or not isinstance(status, str):
        raise TypeError("tenant_id and status must be strings")
    sql = (
        "SELECT order_id, tenant_id, customer, amount, status"
        " FROM orders"
        " WHERE tenant_id = " + _sql_literal(tenant_id) +
        " AND status = " + _sql_literal(status) +
        " ORDER BY order_id"
    )
    return conn.execute(sql).fetchall()
